contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);

        // put some Ether into c through a state-changing top-level call
        c.sendMoney(address(this), amount); if (__ESBMC_reverted()) return;

        uint cBefore = address(c).balance;
        uint selfBefore = address(this).balance;

        // deciding call: owner (this contract) withdraws all from c
        c.withdrawAll(); if (__ESBMC_reverted()) return;

        uint cAfter = address(c).balance;
        uint selfAfter = address(this).balance;

        // withdrawAll must drain c to zero and credit the owner with the prior balance
        assert(cAfter == 0 && cBefore >= cAfter && selfAfter == selfBefore + cBefore);
    }
}

